docs.validate_doc_update:
function(newDoc, oldDoc, userCtx, secObj) {
  if (newDoc._deleted === true) { return; }
  if (newDoc._id && newDoc._id.indexOf('_design/') === 0) { return; }

  var allowedTypes = ['customer','staff','product','voucher','shipping_method','cart','order'];
  if (!newDoc.type || allowedTypes.indexOf(newDoc.type) === -1) {
    throw({forbidden: 'type is required and must be a supported document type'});
  }

  if (newDoc.schema_version !== 1) {
    throw({forbidden: 'schema_version must be 1'});
  }

  if (newDoc.type === 'product') {
    if (!newDoc.legacy_id || !newDoc.name || !newDoc.category) {
      throw({forbidden: 'product requires legacy_id, name and category'});
    }
    if (!Array.isArray(newDoc.variants)) {
      throw({forbidden: 'product.variants must be an array'});
    }
  }

  if (newDoc.type === 'cart') {
    if (!newDoc.customer_id || !Array.isArray(newDoc.items)) {
      throw({forbidden: 'cart requires customer_id and items[]'});
    }
  }

  if (newDoc.type === 'order') {
    var statuses = ['pending','confirmed','packing','shipping','delivered','cancelled'];
    if (statuses.indexOf(newDoc.status) === -1) {
      throw({forbidden: 'invalid order status'});
    }
    if (!newDoc.receiver || !newDoc.receiver.name || !newDoc.receiver.phone || !newDoc.receiver.address) {
      throw({forbidden: 'order.receiver requires name, phone and address'});
    }
    if (!Array.isArray(newDoc.items) || newDoc.items.length === 0) {
      throw({forbidden: 'order.items must be a non-empty array'});
    }
    if (!newDoc.totals || newDoc.totals.grand_total < 0) {
      throw({forbidden: 'order.totals.grand_total must be >= 0'});
    }
    if (!Array.isArray(newDoc.status_history)) {
      throw({forbidden: 'order.status_history must be an array'});
    }
  }
}
